out=[row[:] for row in grid]
markers=[(4,19),(5,13),(9,20),(13,7),(14,17)]
for mr,mc in markers:
 for r in range(5,9):
  for c in range(5,10):
   if grid[r][c]!=3:
    y=mr+(r-5)-2; x=mc+(c-5)-1
    if 0<=y<17 and 0<=x<23: out[y][x]=grid[r][c]
print('\n'.join(' '.join(map(str,row)) for row in out))

